from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(2))  # D0..D1
    units = list(range(10))  # U0..U9
    supplies = list(range(3))  # S0..S2
    days = list(range(4))  # Day0..Day3

    demands = [[[33.43, 16.03, 16.89, 48.12], [36.65, 35.19, 37.36, 12.31], [34.56, 30.56, 32.32, 28.25]], [[36.44, 41.82, 24.62, 39.71], [22.45, 39.17, 40.23, 47.87], [41.83, 29.04, 34.24, 41.19]], [[44.21, 42.1, 10.96, 33.88], [42.22, 42.52, 24.11, 29.58], [23.94, 41.88, 42.66, 44.66]], [[29.95, 17.14, 29.2, 40.84], [15.8, 33.45, 30.6, 36.9], [44.5, 44.84, 36.83, 31.14]], [[19.27, 28.51, 22.56, 41.14], [46.66, 32.17, 10.81, 42.88], [35.49, 12.81, 35.75, 23.64]], [[18.63, 13.66, 22.84, 33.15], [43.83, 33.59, 31.1, 32.6], [13.25, 44.78, 18.73, 17.8]], [[40.98, 28.91, 23.88, 43.31], [30.26, 11.64, 32.03, 28.78], [22.32, 21.97, 24.86, 46.78]], [[12.06, 47.0, 28.06, 45.65], [29.82, 26.06, 12.02, 23.62], [11.3, 42.63, 17.4, 43.45]], [[11.79, 13.73, 21.75, 38.2], [24.86, 11.84, 43.56, 36.36], [41.2, 37.56, 21.79, 24.47]], [[42.37, 32.07, 16.06, 10.57], [49.0, 19.14, 44.12, 11.24], [41.31, 39.86, 47.72, 11.58]]]
    depot_supplies = [[[181.53, 120.77, 103.39, 164.15], [244.53, 129.29, 189.49, 146.94], [214.14, 208.27, 223.45, 226.93]], [[136.34, 119.76, 144.14, 213.87], [239.61, 154.77, 139.25, 187.35], [207.95, 179.15, 178.8, 187.03]]]
    transport_costs = [[3.68, 4.41, 3.92, 2.74, 1.76, 3.97, 3.35, 4.63, 1.06, 3.19], [1.14, 3.95, 1.31, 4.68, 1.31, 2.52, 2.23, 1.04, 2.22, 1.65]]
    risk_costs = [[196.5, 57.27, 79.59, 110.74, 166.31, 164.45, 81.96, 111.65, 139.02, 168.61], [104.5, 196.04, 199.49, 173.95, 131.15, 106.13, 50.21, 53.07, 112.39, 191.0]]
    supply_volumes = [1.8, 1.89, 1.48]
    penalty_costs = [52.33, 71.33, 90.37]
    vehicle_cost = 10.0
    vehicle_capacity = 116.0
    total_vehicles = 12

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
